  position: relative;
  padding: 5vh 0 10vh;
  box-sizing: border-box;
  width: 100vw;
  height: 100vh;
  background-color: #000;
  display: flex;
  overflow-x: hidden;
}
.viewport .video-container {
  position: relative;
  width: 100%;
}
.viewport .video-container.video-container-attech {
  display: flex;
  align-items: center;
  overflow-y: hidden;
  height: 100%;
  flex-direction: column;
}
.viewport .video-container.video-container-in-sharing {
  width: min(20vw, 264px);
  flex-shrink: 0;
}
.viewport .video-container.single-video-container {
  display: flex;
  align-items: center;
  justify-content: center;
}
.viewport .video-container .single-video-wrap {
  width: 100%;
  aspect-ratio: 16/9;
  height: auto;
  position: relative;
  max-height: 100%;
}
.viewport .video-container .video-canvas {
  width: 100%;
  height: 100%;
}
.viewport .video-container .self-video {
  position: absolute;
  width: 189px;
  height: 143px;
  top: 50px;
  right: 30px;
  z-index: 2;
  display: none;
  transform: scaleX(-1);
}
.viewport .video-container .self-video.single-self-video {
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
}
.viewport .video-container .self-video.self-video-show {
  display: block;
}
.viewport .video-container .ant-radio-button-wrapper {
  z-index: 1;
}
.viewport .video-container .video-container-wrap {
  flex: 1 1;
  width: 100%;
  height: 100%;
}
.viewport .video-container .user-list {
  height: 100%;
  display: grid;
}
.viewport .video-container .user-list .video-cell {
  position: relative;
  margin: 12px;
}
.viewport .video-container .user-list .video-cell.video-cell-spotlight {
  grid-row-start: span 2;
  grid-column-start: span 2;
}
.viewport .video-container .user-list .video-cell .aspact-ratio {
  position: relative;
  max-width: 100%;
  max-height: 100%;
  height: 100%;
  overflow: hidden;
}
.viewport .video-container .user-list .video-cell .change-video-resolution {
  position: absolute;
}
.viewport .video-container .user-list .video-cell .video-player {
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}
.viewport .unified-self-view {
  position: fixed;
  aspect-ratio: 4/3;
  top: 50px;
  right: 50px;
  z-index: 2;
  cursor: all-scroll;
  touch-action: none;
}
.viewport .unified-self-view-container {
  width: 100%;
  aspect-ratio: 4/3;
  background-color: black;
}
.viewport .video-player {
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}
.viewport .avatar-list {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  overflow: hidden;
  padding: 0;
  margin: 0;
}
.viewport .video-operations {
  position: absolute;
  left: 0;
  bottom: 0;
}
.viewport .avatar-wrap {
  position: absolute;
  pointer-events: auto;
  list-style: none;
  top: 0;
  left: 0;
}
.viewport .avatar-wrap-dragging {
  z-index: 10;
}
.viewport .single-view-avatar {
  top: 0;
  left: 0;
}
.viewport .self-video-tag {
  display: none;
  position: absolute;
}`, "",{"version":3,"sources":["webpack://./src/feature/video/video.scss"],"names":[],"mappings":"AAAA;EACE,kBAAA;EACA,mBAAA;EACA,sBAAA;EACA,YAAA;EACA,aAAA;EACA,sBAAA;EACA,aAAA;EACA,kBAAA;AACF;AAAE;EACE,kBAAA;EACA,WAAA;AAEJ;AADI;EACE,aAAA;EACA,mBAAA;EACA,kBAAA;EACA,YAAA;EACA,sBAAA;AAGN;AAAI;EACE,uBAAA;EACA,cAAA;AAEN;AAAI;EACE,aAAA;EACA,mBAAA;EACA,uBAAA;AAEN;AAAI;EACE,WAAA;EACA,kBAAA;EACA,YAAA;EACA,kBAAA;EACA,gBAAA;AAEN;AACI;EACE,WAAA;EACA,YAAA;AACN;AACI;EACE,kBAAA;EACA,YAAA;EACA,aAAA;EACA,SAAA;EACA,WAAA;EACA,UAAA;EACA,aAAA;EACA,qBAAA;AACN;AAAM;EACE,WAAA;EACA,YAAA;EACA,MAAA;EACA,OAAA;AAER;AAAM;EACE,cAAA;AAER;AACI;EACE,UAAA;AACN;AACI;EACE,SAAA;EACA,WAAA;EACA,YAAA;AACN;AAEI;EACE,YAAA;EACA,aAAA;AAAN;AAEM;EACE,kBAAA;EACA,YAAA;AAAR;AACQ;EACE,sBAAA;EACA,yBAAA;AACV;AACQ;EACE,kBAAA;EACA,eAAA;EACA,gBAAA;EACA,YAAA;EACA,gBAAA;AACV;AACQ;EACE,kBAAA;AACV;AACQ;EACE,cAAA;EACA,kBAAA;EACA,MAAA;EACA,OAAA;EACA,QAAA;EACA,SAAA;AACV;AAIE;EACE,eAAA;EACA,iBAAA;EACA,SAAA;EACA,WAAA;EACA,UAAA;EACA,kBAAA;EACA,kBAAA;AAFJ;AAKE;EACE,WAAA;EACA,iBAAA;EACA,uBAAA;AAHJ;AAKE;EACE,cAAA;EACA,kBAAA;EACA,MAAA;EACA,OAAA;EACA,QAAA;EACA,SAAA;AAHJ;AAME;EACE,kBAAA;EACA,MAAA;EACA,OAAA;EACA,WAAA;EACA,YAAA;EACA,oBAAA;EACA,gBAAA;EACA,UAAA;EACA,SAAA;AAJJ;AAME;EACE,kBAAA;EACA,OAAA;EACA,SAAA;AAJJ;AAME;EACE,kBAAA;EACA,oBAAA;EACA,gBAAA;EACA,MAAA;EACA,OAAA;AAJJ;AAME;EACE,WAAA;AAJJ;AAME;EACE,MAAA;EACA,OAAA;AAJJ;AAME;EACE,aAAA;EACA,kBAAA;AAJJ","sourcesContent":[".viewport {\n  position: relative;\n  padding: 5vh 0 10vh;\n  box-sizing: border-box;\n  width: 100vw;\n  height: 100vh;\n  background-color: #000;\n  display: flex;\n  overflow-x: hidden;\n  .video-container {\n    position: relative;\n    width: 100%;\n    &.video-container-attech {\n      display: flex;\n      align-items: center;\n      overflow-y: hidden;\n      height: 100%;\n      flex-direction: column;\n    }\n\n    &.video-container-in-sharing {\n      width: min(20vw, 264px);\n      flex-shrink: 0;\n    }\n    &.single-video-container {\n      display: fle